from pathlib import Path

app_path = Path('src/App.tsx')
app = app_path.read_text()

def need(old: str, new: str, label: str):
    global app
    if old not in app:
        raise SystemExit(f'missing App anchor: {label}')
    app = app.replace(old, new, 1)

app = app.replace(', uploadProjectToTelegram, getProjectCloudStatus, openBeatProject, updateProjectArchiveFromSource, inspectProjectDropSource', '')
need('import { useBeatAssetUpdates } from "./features/edit/useBeatAssetUpdates";\n', 'import { useBeatAssetUpdates } from "./features/edit/useBeatAssetUpdates";\nimport { useBeatProjects } from "./features/projects/useBeatProjects";\n', 'hook import')
