call = anchor + '''  const {\n    openableCloudProjectIds,\n    projectUpdateNotice,\n    hasStoredProject,\n    startProjectAssetUpdate,\n    handleAutoProjectDrop,\n    handleBrowserProjectDrop,\n    handleUploadProjectTelegram,\n    handleOpenProject,\n    handleUpdateProject,\n  } = useBeatProjects({\n    beats,\n    connectionState,\n    rejectOfflineMutation,\n    transitionRuntime,\n    beatsLatestRef,\n    setBeats,\n    setDrawer,\n    runBeatCloudUpdate,\n    setBeatCloudUpdateBusy,\n  });\n\n'''
